n, m = map(int, input().split())
k = int(input())

MOD = 998244353

def add(x, y):
    return ((x + y) % MOD + MOD) % MOD

def mult(x, y):
    return ((x * y) * 1 % MOD + MOD) % MOD

def exp(base, power):
    result = 1
    b = base
    p = power
    while p > 0:
        if p & 1 == 1:
            result = mult(result, b)
        b = mult(b, b)
        p >>= 1
    return result

def inv(x):
    return exp(x, MOD - 2)

dp = [[0] * (k + 1) for _ in range(k + 1)]
dp[0][0] = 1

for i in range(k):
    for j in range(k):
        dp[i + 1][j] = add(dp[i + 1][j], mult(dp[i][j], j))
        dp[i + 1][j + 1] = add(dp[i + 1][j + 1], mult(dp[i][j], n - j))

total = 0
for i in range(1, k + 1):
    total = add(total, mult(dp[k][i], exp(inv(m), i)))

print(total)

